// Función para extraer información de las preguntas
function parsePreguntas(preguntas) {
  const result = {
    formaPago: '',
    autoEntregado: '',
    comentarios: preguntas || ''
  };

  if (!preguntas) return result;

  const preguntasLower = preguntas.toLowerCase();

  if (preguntasLower.includes('contado')) {
    result.formaPago = 'contado';
  } else if (preguntasLower.includes('financiado')) {
    result.formaPago = 'financiado';
  } else if (preguntasLower.includes('plan toyota')) {
    result.formaPago = 'plan toyota';
  }

  if (preguntasLower.includes('sin usado') || preguntasLower.includes('no usado')) {
    result.autoEntregado = 'No';
  } else {
    result.autoEntregado = 'Sí';
  }

  return result;
}

// Función para obtener el código del modelo
function getModeloCode(modeloCompleto) {
  if (!modeloCompleto) return '';

  const modeloLower = modeloCompleto.toLowerCase();

  if (modeloLower.includes('hilux')) {
    return '1';
  } else if (modeloLower.includes('corolla cross')) {
    return '245';
  } else if (modeloLower.includes('corolla') && !modeloLower.includes('cross')) {
    return '2';
  } else if (modeloLower.includes('yaris')) {
    return '227';
  } else if (modeloLower.includes('etios')) {
    return '225';
  } else if (modeloLower.includes('sw4')) {
    return '226';
  } else if (modeloLower.includes('hiace')) {
    return '224';
  } else if (modeloLower.includes('rav4') || modeloLower.includes('rav 4')) {
    return '3';
  }

  return '';
}

// Función para parsear el modelo del vehículo
function parseModelo(modeloCompleto) {
  if (!modeloCompleto) return { modelo: '', version: '', modelo_code: '' };

  const palabras = modeloCompleto.trim().split(' ');
  const modelo = palabras[0] || '';
  const version = palabras.slice(1).join(' ') || '';
  const modelo_code = getModeloCode(modeloCompleto);

  return {
    modelo: modelo,
    version: version,
    modelo_code: modelo_code
  };
}

// Función para limpiar número de teléfono
function limpiarTelefono(telefono) {
  if (!telefono) return '';

  let numero = telefono.toString().replace(/\D/g, '');

  if (numero.startsWith('549')) {
    numero = numero;
  } else if (numero.startsWith('54')) {
    numero = numero;
  }

  return numero;
}

// Función para determinar grupo según origen y sucursal
function determinarGrupo(origen, sucursal) {
  const origenLower = (origen || '').toLowerCase().trim();
  const sucursalLower = (sucursal || '').toLowerCase().trim();

  if (origenLower === 'plan' && sucursalLower === 'mercedes') return '391';
  if (origenLower === 'plan' && sucursalLower === 'corrientes') return '393';
  if (origenLower === 'usado' && sucursalLower === 'corrientes') return '394';
  if (origenLower === 'convencional' && sucursalLower === 'corrientes') return '392';

  return '';
}

// Función para mapear provider
function mapearProvider(provider) {
  const p = (provider || '').toLowerCase().trim();
  if (p === 'plan') return 'TPA';
  if (p === 'convencional') return 'CONVENCIONAL';
  if (p === 'usado') return 'USADOS';
  return (provider || '').toUpperCase();
}

// Procesar los datos de entrada de n8n
const data = $json;

// Parsear información — todo desde data (raíz del JSON)
const preguntasInfo = parsePreguntas(data.resumen || '');
const modeloInfo = parseModelo(data.modelo || '');
const telefonoLimpio = limpiarTelefono(data.from);

// Obtener fecha actual en formato yyyy-MM-dd
const fechaActual = new Date().toISOString().split('T')[0];

// Origen, sucursal y grupo
const origenDetectado = data.origen || '';
const sucursalDetectada = data.sucursal || '';
const grupoAsignado = determinarGrupo(origenDetectado, sucursalDetectada);

// Crear resultado
const resultado = {
  requestdate: fechaActual,
  nombre: data.nombreDeclarado || data.name || '',
  email: data.email || '',
  telefono: telefonoLimpio,

  modelo: modeloInfo.modelo,
  version: modeloInfo.version,
  modelo_code: modeloInfo.modelo_code,
  marca: 'Toyota',
  origen: origenDetectado,
  operacion: data.operacion || '',

  formaPago: preguntasInfo.formaPago,
  autoEntregado: preguntasInfo.autoEntregado,
  comentarios: preguntasInfo.comentarios,

  crm: data.crm || '',
  appkey: data.appkey || '',
  action: data.action || '',
  provider: mapearProvider(data.provider),
  origin: 'Chatbot',
  bocaVenta: 'ITUZ',

  sucursal: sucursalDetectada,
  grupo: grupoAsignado,
};

return [{ json: resultado }];

